kiso/encoding/binary.signature:
koukai sentaku BinaryError {
    InvalidOffset;
    InsufficientData;
    Overflow;
    MalformedVarint;
}

kiso/fs.signature:
koukai sentaku FsError {
    NotFound(string);
    PermissionDenied(string);
    Closed(string);
    InvalidArgument(string);
    NoSpace(string);
    InvalidPath(string);
    IOFailure(string);
}

kiso/io.signature:
koukai sentaku IoError {
    Closed;
    InvalidArgument;
    NoProgress;
    UnexpectedEOF;
    Other(string);
}

kiso/utf8.signature:
koukai kata DecodeResult {
    value: rune;
    width: int64;
    valid: bool;
}
